#!/usr/bin/env bash
# One command per JR編 COMBINED episode (GAME OVER run → caught → GAME OVER on black → lesson → CONTINUE? → CLEAR run →
# kaiju gag → end card → union sources), combined/CONTRACT.md "Pipeline"; configs web3d/shibuya/series/variants/jr/combined/
# <pair>.json (generated by tools/combined_configs.mjs), page variant=combined/<pair>. Docs: docs/COMBINED.md.
#   tools/render_combined.sh <pair>             validate → render ONLY the NEW beats (≤300-frame resumable segments) → extract
#                                               the reused ranges from the source bodies → join with the pinned opening, ONE
#                                               re-encode → audio mix (combined cue sheet) → mux → verify → report → contact
#                                               → $OUT/<pair>.mp4 + $OUT/<pair>-contact.jpg (+ $WORK/<pair>/report.json)
#   tools/render_combined.sh all                gate taxi zone alt
#   tools/render_combined.sh check [<pair>]     configs == generator, combined validator (+ parts), reuse maps, source bodies
#                                               located + asserted (840 frames, beat edges), pinned opening (no browser)
#   tools/render_combined.sh plan [<pair>]      pieces (opening / reuse / new) + segment plan of the NEW ranges with a time
#                                               estimate per segment; fails if one segment would exceed 45 min
#   tools/render_combined.sh stills <pair> T1,T2[,…]|new   preview PNGs at body seconds ('new' = every NEW beat incl. the
#                                               caught flash/black + the fix frame) → $WORK/<pair>/stills/ (AGENTS default 8000)
#   tools/render_combined.sh contact <pair>     contact sheet of $OUT/<pair>.mp4, every combined beat labelled
# SMOKE=1 tools/render_combined.sh <pair>      plumbing test WITHOUT a browser: NEW pieces not rendered yet become black
#                                               frames; extraction + join + audio + mux + verify + accuracy + contact run for
#                                               real → $WORK/smoke/<pair>.mp4 (OUT defaults there; never the deliverables).
#
# Pieces: tools/variant_cues.mjs --reuse-map → variant-system.mjs reuseMap: consecutive NEW beats form one piece (rendered
# with tools/record_variant.py --variant combined/<pair> --part body --start-frame a --end-frame b, SEG_FRAMES ≤ 300 frames
# per segment, each its own browser session under `flock /tmp/ssl-halloween-browser.lock` — one browser on the box), a
# segment is done only when its frame count matches (fragmented MP4 → re-running resumes). Consecutive reused beats that
# continue the same source body form one piece, decoded frame-accurately (trim=start_frame:end_frame) from
# $SRC/<variant>/body-*/body.mp4 (non-test dir; 840 frames + beat edges asserted by tools/combined_pipeline.py sources).
# Join: pinned opening (OPENING_MP4, 426 frames, never re-rendered) + every piece in timeline order → raw yuv420p on one pipe
# → ONE libx264 encode (crf 16, 1080x1920, yuv420p, 30 fps). Audio: variant_cues.mjs combined/<pair> --out cues.json (cue sheet
# over opening + the whole combined body) → tools/audio/run.sh mix --strict (the cue sheet's segments master the opening on its own) → tools/audio/mux.sh (AAC 48 kHz
# stereo). Verify: frames, format, AAC, EBU R128 −15.5…−12.5 LUFS + true peak ≤ −1 dBTP, frame-accuracy spot check of every
# reused piece (PSNR vs source frame ±1) → report.json (segments with wall time, join, accuracy, mix).
# Env: OUT (deliverables, default /workspace/demos/halloween-escape-series/jr-combined), WORK (default $L/render),
#      SRC (source renders, default …/variants/render — read only), OPENING_MP4 (pinned opening), SEG_FRAMES (≤300),
#      MAX_SEGS (render ≤N new segments then exit 3 → one scheduler job per ≤45 min segment), AGENTS, PR, PYBIN,
#      CRF (16), X264_PRESET (medium; SMOKE: veryfast), BROWSER_LOCK, SMOKE.
# SEGMENT PLAN (s/frame incl. PNG+encode, full crowd, shared 8-CPU box; tools/render_variant.sh header + estimates for the new
#   shots): caught-pov ≈3.6 · black ≈0.6 · continue-bg ≈2.9 · kaiju-skyline ≈4.4 · card-bg ≈2.9 · detour ≈3.2 · alt-platform ≈2.8,
#   + 8 min start-up per segment. NEW per pair: caught+over-stamp 135 f (1 job ≈16 min), continue 90 f (≈13 min), kaiju+endcard+
#   sources 285 f (≈26 min); zone/alt + clear-result+clear-stamp 195 f (≈19 min). Every job ≤ 45 min.
set -euo pipefail
repo_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd -- "$repo_dir"
L=${COMBINED_LOGS:-/workspace/projects/logs/ssl-claude-halloween/combined}
WORK=${WORK:-$L/render}
SRC=${SRC:-/workspace/projects/logs/ssl-claude-halloween/variants/render}
OPENING_MP4=${OPENING_MP4:-$SRC/opening-dde6ef8ff89d1617/opening.mp4}
if [ -n "${SMOKE:-}" ]; then OUT=${OUT:-$WORK/smoke}; else OUT=${OUT:-/workspace/demos/halloween-escape-series/jr-combined}; fi
SEG_FRAMES=${SEG_FRAMES:-300}; [ "$SEG_FRAMES" -le 300 ] || { echo "SEG_FRAMES must be ≤ 300 (contract)" >&2; exit 2; }
PR=${PR:-1}
CRF=${CRF:-16}
X264_PRESET=${X264_PRESET:-$([ -n "${SMOKE:-}" ] && echo veryfast || echo medium)}
LOCK=${BROWSER_LOCK:-/tmp/ssl-halloween-browser.lock}
PAIRS=(gate taxi zone alt)
OPENING=_opening
EXTRA=(--opening "$OPENING")
[ -n "${AGENTS:-}" ] && EXTRA+=(--agents "$AGENTS")
[ "$PR" != 1 ] && EXTRA+=(--pr "$PR")
mkdir -p "$WORK"
log() { echo "[render_combined $(date +%T)] $*"; }
frames_in() { [ -s "$1" ] || { echo 0; return; }; ffprobe -v error -select_streams v:0 -count_packets -show_entries stream=nb_read_packets -of csv=p=0 "$1" 2>/dev/null || echo 0; }
cues() { node tools/variant_cues.mjs "$@" --opening "$OPENING"; }
jsonv() { python3 -c "import json,sys;d=json.load(open(sys.argv[1]));print(eval(sys.argv[2],{'d':d}))" "$@"; }
PIPE=(python3 tools/combined_pipeline.py)
valid_pair() { case " ${PAIRS[*]} " in *" $1 "*) ;; *) echo "unknown pair '$1' (${PAIRS[*]})" >&2; exit 2 ;; esac; }

# recorder interpreter (lazy: check/plan/SMOKE never need it): PYBIN → $WORK/.venv-rec → the variants venv (read only) →
# build $WORK/.venv-rec → uv run
REC=()
recorder() { [ ${#REC[@]} -gt 0 ] && return
  local py=''
  for c in "${PYBIN:-}" "$WORK/.venv-rec/bin/python" "$SRC/.venv-rec/bin/python"; do
    [ -n "$c" ] && [ -x "$c" ] && "$c" -c 'import playwright,PIL' 2>/dev/null && { py=$c; break; }; done
  if [ -z "$py" ]; then { uv venv --quiet "$WORK/.venv-rec" && uv pip install --quiet --python "$WORK/.venv-rec/bin/python" playwright pillow; } >&2 || rm -rf "$WORK/.venv-rec"
    "$WORK/.venv-rec/bin/python" -c 'import playwright,PIL' 2>/dev/null && py=$WORK/.venv-rec/bin/python; fi
  if [ -n "$py" ]; then REC=("$py" tools/record_variant.py); else REC=(uv run --quiet --no-project --with playwright --with pillow python tools/record_variant.py); fi; }
contact_py() { local py=python3; python3 -c 'import PIL' 2>/dev/null || { recorder; py=${REC[0]}; [ "$py" = uv ] && py="uv run --quiet --no-project --with pillow python"; }; $py tools/record_variant.py contact "$@"; }

# prepare <pair>: validation + reuse map + located sources + cue sheet + timeline in $WORK/<pair>/
prepare() { local pair=$1 w=$WORK/$1 id=combined/$1; mkdir -p "$w"
  cues "$id" --check --quiet || { echo "config $id invalid" >&2; exit 1; }
  node tools/variant_cues.mjs --reuse-map "$id" >"$w/map.json"
  "${PIPE[@]}" sources --map "$w/map.json" --src-root "$SRC" --out "$w/sources.json"
  cues "$id" --out "$w/cues.json" --timeline "$w/timeline.json" --quiet
  local on; on=$(jsonv "$w/timeline.json" "d['parts']['opening']['frames']")
  [ "$(frames_in "$OPENING_MP4")" -eq "$on" ] || { echo "pinned opening $OPENING_MP4: $(frames_in "$OPENING_MP4")/$on frames" >&2; exit 1; }
  BODYDIR=$w/body-$(cues --part-key "$id"); mkdir -p "$BODYDIR"; }

# new_pieces <map.json> → lines "f0 f1 beats"
new_pieces() { python3 -c "import json,sys;[print(p['f0'],p['f1'],'+'.join(p['beats'])) for p in json.load(open(sys.argv[1]))['pieces'] if p['mode']=='new']" "$1"; }

# render_piece <pair> <f0> <f1> <label>: segments of ≤SEG_FRAMES into $BODYDIR/new-f0-f1/, then $BODYDIR/new-f0-f1.mp4
render_piece() { local pair=$1 f0=$2 f1=$3 lab=$4 name dir list a b k=0 s got t0
  name=$(printf 'new-%04d-%04d' "$f0" "$f1"); dir=$BODYDIR/$name
  if [ "$(frames_in "$BODYDIR/$name.mp4")" -eq $((f1-f0)) ]; then log "$pair $lab ($f0–$f1) done"; return; fi
  mkdir -p "$dir"; list=$dir/concat.txt; : >"$list"
  for ((a=f0; a<f1; a+=SEG_FRAMES)); do b=$((a+SEG_FRAMES)); ((b>f1)) && b=$f1; s=$(printf '%s/seg-%02d' "$dir" "$k")
    if [ "$(frames_in "$s.mp4")" -eq $((b-a)) ] && [ -s "$s.jsonl" ]; then log "$pair $lab seg $k ($a–$b) done"
    else
      if [ -n "${MAX_SEGS:-}" ] && [ "${SEGS_DONE:-0}" -ge "$MAX_SEGS" ]; then log "MAX_SEGS=$MAX_SEGS reached; re-run to continue"; exit 3; fi
      SEGS_DONE=$(( ${SEGS_DONE:-0} + 1 )); recorder
      rm -f "$s.mp4" "$s.jsonl"; log "$pair $lab seg $k: body frames $a–$b → $s.mp4 (waiting for the browser lock)"; t0=$SECONDS
      flock "$LOCK" "${REC[@]}" --variant "combined/$pair" --part body --output "$s.mp4" --log "$s.jsonl" --summary "$s.json" --start-frame "$a" --end-frame "$b" "${EXTRA[@]}" 2>&1 \
        | grep --line-buffered -v 'toNonIndexed' | tee "$s.log"
      log "$pair $lab seg $k finished in $((SECONDS-t0)) s (incl. lock wait)"; echo "$((SECONDS-t0))" >"$s.wall"
      got=$(frames_in "$s.mp4"); [ "$got" -eq $((b-a)) ] || { echo "$pair $lab segment $k incomplete: $got/$((b-a)) frames (re-run to resume)" >&2; exit 1; }
    fi
    echo "file '$s.mp4'" >>"$list"; k=$((k+1)); done
  ffmpeg -hide_banner -loglevel error -y -f concat -safe 0 -i "$list" -c copy -movflags +faststart "$BODYDIR/$name.mp4"
  got=$(frames_in "$BODYDIR/$name.mp4"); [ "$got" -eq $((f1-f0)) ] || { echo "$BODYDIR/$name.mp4: $got/$((f1-f0)) frames" >&2; exit 1; }
  log "$pair $lab: $BODYDIR/$name.mp4 ($((f1-f0)) frames)"; }

render_pair() { local pair=$1 w=$WORK/$1 v D n on f0 f1 lab
  valid_pair "$pair"; prepare "$pair"
  if [ -z "${SMOKE:-}" ]; then while read -r f0 f1 lab; do render_piece "$pair" "$f0" "$f1" "$lab"; done < <(new_pieces "$w/map.json")
  else log "SMOKE: NEW pieces not rendered yet → black frames; output → $OUT"; w=$w/smoke; mkdir -p "$w"; cp "$WORK/$pair"/{map,sources,cues,timeline}.json "$w/"; fi
  mkdir -p "$OUT"; v=$OUT/$pair.mp4
  on=$(jsonv "$w/timeline.json" "d['parts']['opening']['frames']"); n=$(jsonv "$w/timeline.json" "d['frames']"); D=$(jsonv "$w/timeline.json" "d['duration']")
  "${PIPE[@]}" join --map "$w/map.json" --sources "$w/sources.json" --opening "$OPENING_MP4" --opening-frames "$on" --new-dir "$BODYDIR" \
    --out "$w/video.mp4" --report "$w/join.json" --crf "$CRF" --preset "$X264_PRESET" ${SMOKE:+--smoke}
  # audio: the cue sheet covers opening + the whole combined body; the opening is mastered as its own segment
  if [ -x tools/audio/run.sh ] && [ -f tools/audio/mix.py ]; then
    tools/audio/run.sh mix --cues "$w/cues.json" --duration "$D" --out "$w/mix.wav" --report "$w/mix.json" --strict
  else log "tools/audio missing → silent track (stub)"; ffmpeg -hide_banner -loglevel error -y -f lavfi -i anullsrc=r=48000:cl=stereo -t "$D" -c:a pcm_s16le "$w/mix.wav"; fi
  if [ -x tools/audio/mux.sh ]; then tools/audio/mux.sh "$w/video.mp4" "$w/mix.wav" "$v"
  else ffmpeg -hide_banner -loglevel error -y -i "$w/video.mp4" -i "$w/mix.wav" -map 0:v:0 -map 1:a:0 -c:v copy -c:a aac -b:a 192k -ar 48000 -ac 2 -shortest -movflags +faststart "$v"; fi
  verify_pair "$pair" "$w" "$v" "$n" "$on"
  contact_py --video "$v" --timeline "$w/timeline.json" --out "$OUT/$pair-contact.jpg" >/dev/null && log "contact sheet $OUT/$pair-contact.jpg"
  log "$pair done: $v"; }

verify_pair() { local pair=$1 w=$2 v=$3 n=$4 on=$5 rc=0 segs
  ffmpeg -hide_banner -nostats -i "$v" -vn -af ebur128=peak=true:framelog=quiet -f null - 2>"$w/ebur128.txt" || true
  "${PIPE[@]}" accuracy --video "$v" --map "$w/map.json" --sources "$w/sources.json" --opening "$OPENING_MP4" --opening-frames "$on" --out "$w/accuracy.json" || rc=1
  # per-segment summaries (frames, wall time, ms/frame, soft issues) of the NEW pieces
  segs=$w/segments.json
  python3 - "$BODYDIR" "$segs" <<'EOF'
import json,sys,glob,os
out=[]
for f in sorted(glob.glob(os.path.join(sys.argv[1],'new-*','seg-*.json'))):
    s=json.load(open(f));w=f[:-5]+'.wall'
    out.append({k:s.get(k) for k in ('output','frames','wall_s','ms_per_frame','soft')}|({'job_wall_s':int(open(w).read())} if os.path.exists(w) else {}))
json.dump(out,open(sys.argv[2],'w'),indent=1)
EOF
  "${PIPE[@]}" verify --video "$v" --frames "$n" --ebur "$w/ebur128.txt" --out "$w/report.json" \
    --extra "pair=\"$pair\"" --extra "smoke=$([ -n "${SMOKE:-}" ] && echo true || echo false)" --extra "opening=\"$OPENING_MP4\"" \
    --extra "map=$w/map.json" --extra "sources=$w/sources.json" --extra "join=$w/join.json" --extra "accuracy=$w/accuracy.json" \
    --extra "segments=$segs" --extra "mix=$w/mix.json" || rc=1
  [ $rc -eq 0 ] || { echo "verify failed for $pair (see $w/report.json)" >&2; exit 1; }
  log "verified $v → $w/report.json"; }

plan_pair() { local pair=$1 w=$WORK/$1; valid_pair "$pair"; prepare "$pair" >/dev/null
  python3 - "$w/map.json" "$w/timeline.json" "$SEG_FRAMES" "$BODYDIR" <<'EOF'
import json,sys,os
m=json.load(open(sys.argv[1]));tl=json.load(open(sys.argv[2]));S=int(sys.argv[3]);bd=sys.argv[4]
# s/frame (wall, incl. PNG + encode) per shot key: tools/render_variant.sh plan + estimates for the combined shots; +WARM s/segment
MS={'op-flythrough':2.9,'topdown':2.9,'aerial':4.4,'eye-walk':3.0,'gate-queue':3.6,'gate-newsouth':2.6,'zone-edge':3.6,'detour':3.2,'routemap':2.4,
    'alt-platform':2.8,'taxi-west':3.2,'taxi-sakura':3.2,'interior':4.5,'card-bg':2.9,'caught-pov':3.6,'black':.6,'continue-bg':2.9,'kaiju-skyline':4.4}
WARM=480;CAP=45*60;worst=0;total=0;beats=m['beats']
cost=lambda f:next((MS.get(b['shot'],4.5) for b in beats if b['f0']<=f<b['f1']),4.5)
print(f"{m['id']}: opening {tl['parts']['opening']['frames']} f (pinned) + body {m['frames']} f = {tl['frames']} frames, {tl['duration']:.2f} s")
for p in m['pieces']:
    lab='+'.join(p['beats'])
    if p['mode']=='reuse': print(f"  reuse {p['f0']:4d}–{p['f1']:4d} ({p['frames']:3d} f) {lab:40s} ← {p['src']['variant']} [{p['src']['f0']}–{p['src']['f1']})");continue
    segs=[]
    for a in range(p['f0'],p['f1'],S):
        b=min(a+S,p['f1']);sec=WARM+sum(cost(f) for f in range(a,b));worst=max(worst,sec);total+=sec;segs.append(f'{a}-{b} ~{sec/60:.0f} min')
    done=os.path.exists(os.path.join(bd,f"new-{p['f0']:04d}-{p['f1']:04d}.mp4"))
    print(f"  NEW   {p['f0']:4d}–{p['f1']:4d} ({p['frames']:3d} f) {lab:40s} → {' | '.join(segs)}{'  [rendered]' if done else ''}")
print(f"  render total ~{total/60:.0f} min · worst segment ~{worst/60:.0f} min (cap 45 min):",'OK' if worst<=CAP else 'TOO LONG -> lower SEG_FRAMES')
sys.exit(0 if worst<=CAP else 1)
EOF
}

stills_pair() { local pair=$1 times=$2 w=$WORK/$1; valid_pair "$pair"; prepare "$pair" >/dev/null
  if [ "$times" = new ]; then times=$(python3 -c "
import json,sys;m=json.load(open(sys.argv[1]));t=[]
K={'caught':[.5,1.5,1.8,2.3],'over-stamp':[1.0,1.9],'continue':[.6,2.7],'kaiju':[1.0,2.6],'clear-result':[.5,2.4],'clear-stamp':[1.0]}
for b in m['beats']:
  if b['mode']!='new':continue
  for x in K.get(b['id'],[b['frames']/30*.6]): t.append(round(b['f0']/30+x,3))
print(','.join(map(str,t)))" "$w/map.json"); fi
  recorder; mkdir -p "$w/stills"
  log "stills $pair at body s $times (waiting for the browser lock)"
  AG=(); [ -z "${AGENTS:-}" ] && AG=(--agents 8000)
  flock "$LOCK" "${REC[@]}" --variant "combined/$pair" --part body --stills "$w/stills" --stills-at "$times" "${EXTRA[@]}" "${AG[@]}" 2>&1 | grep --line-buffered -v toNonIndexed
  echo "$w/stills"; }

check_all() { local rc=0 p
  node tools/combined_configs.mjs --check || { echo "combined configs differ from tools/combined_configs.mjs (run: node tools/combined_configs.mjs --write)" >&2; rc=1; }
  node tools/variant_cues.mjs --validate-combined --opening "$OPENING" >"$WORK/validate-combined.json" || rc=1
  python3 -c "
import json,sys;d=json.load(open(sys.argv[1]))
for k,v in d['combined'].items(): print(f\"{k}: {'OK' if v['ok'] else 'INVALID'} · {v['duration']} s · {v['frames']} frames\"+''.join(f'\n  error: {e}' for e in v['errors'])+''.join(f'\n  warning: {e}' for e in v['warnings']))" "$WORK/validate-combined.json"
  [ "$(frames_in "$OPENING_MP4")" -eq 426 ] && echo "pinned opening: $OPENING_MP4 (426 frames)" || { echo "pinned opening $OPENING_MP4 missing / not 426 frames" >&2; rc=1; }
  for p in "${@:-${PAIRS[@]}}"; do valid_pair "$p"; mkdir -p "$WORK/$p"
    node tools/variant_cues.mjs --reuse-map "combined/$p" >"$WORK/$p/map.json" && "${PIPE[@]}" sources --map "$WORK/$p/map.json" --src-root "$SRC" --out "$WORK/$p/sources.json" || rc=1; done
  [ $rc -eq 0 ] && echo "check OK" || echo "check FAILED" >&2
  return $rc; }

case "${1:-}" in
  ''|-h|--help) awk 'NR>1 && /^#/{print;next} NR>1{exit}' "$0"; exit 2 ;;
  all) for p in "${PAIRS[@]}"; do render_pair "$p"; done ;;
  check) shift; check_all "$@" ;;
  plan) shift; rc=0; for p in "${@:-${PAIRS[@]}}"; do plan_pair "$p" || rc=1; done; exit $rc ;;
  stills) [ $# -ge 3 ] || { echo "usage: $0 stills <pair> T1,T2|new" >&2; exit 2; }; stills_pair "$2" "$3" ;;
  contact) valid_pair "${2:-}"; w=$WORK/$2; [ -n "${SMOKE:-}" ] && w=$w/smoke; [ -f "$w/timeline.json" ] || cues "combined/$2" --timeline "$w/timeline.json" --quiet
           contact_py --video "$OUT/$2.mp4" --timeline "$w/timeline.json" --out "$OUT/$2-contact.jpg" ;;
  *) render_pair "$1" ;;
esac
